changeSet.sql:
CREATE TABLE answers (
    id          UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    question_id UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
    body        TEXT NOT NULL,
    author_id   UUID NOT NULL REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_answers_question_id_created
    ON answers(question_id, created_at);
CREATE INDEX idx_answers_author_id
    ON answers(author_id);

rollback.sql:
DROP INDEX IF EXISTS idx_answers_author_id;
DROP INDEX IF EXISTS idx_answers_question_id_created;
DROP TABLE answers;
